CREATE OR REPLACE VIEW ict_demo.v_service_register AS SELECT s.service_code,s.service_name,s.service_tier,o.owner_code,s.status,s.support_hours,COUNT(a.asset_id) AS asset_count FROM ict_demo.services s JOIN ict_demo.service_owners o USING(owner_id) LEFT JOIN ict_demo.assets a USING(service_id) GROUP BY s.service_code,s.service_name,s.service_tier,o.owner_code,s.status,s.support_hours;
CREATE OR REPLACE VIEW ict_demo.v_open_work_queue AS SELECT w.item_ref,s.service_code,s.service_name,w.item_type,w.summary,w.priority,w.status,w.opened_at,w.due_at,w.owner_ref FROM ict_demo.work_items w LEFT JOIN ict_demo.services s USING(service_id) WHERE w.status NOT IN('resolved','cancelled');
CREATE OR REPLACE VIEW ict_demo.v_overdue_work AS SELECT * FROM ict_demo.v_open_work_queue WHERE due_at<CURRENT_TIMESTAMP;
CREATE OR REPLACE VIEW ict_demo.v_asset_lifecycle AS SELECT asset_type,environment,lifecycle,COUNT(*) AS asset_count FROM ict_demo.assets GROUP BY asset_type,environment,lifecycle;